-- Catalog expansion. These client-supplied XAF ranges are estimates, not approved billing prices.
ALTER TABLE catalog_item ADD COLUMN IF NOT EXISTS price_min_xaf BIGINT NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS price_max_xaf BIGINT NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS image_path VARCHAR(255) NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS icon_path VARCHAR(255) NOT NULL DEFAULT '';
UPDATE catalog_item SET published=0 WHERE code IN ('PL-014','PL-006','PL-021','EL-021','EL-008','AP-018','AP-025');
ON DUPLICATE KEY UPDATE category=VALUES(category),trade_code=VALUES(trade_code),name_en=VALUES(name_en),name_fr=VALUES(name_fr),description=VALUES(description),price_min_xaf=VALUES(price_min_xaf),price_max_xaf=VALUES(price_max_xaf),price_xaf=VALUES(price_xaf),planned_minutes=VALUES(planned_minutes),published=1,version_code=VALUES(version_code),image_path=VALUES(image_path),icon_path=VALUES(icon_path);
